+package org.apache.streampipes.manager.endpoint;
+
+import java.io.IOException;
+import java.net.Inet4Address;
+import java.net.Inet6Address;
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+
+final class EndpointUrlValidator {
+
+  private EndpointUrlValidator() {
+  }
+
+  static URI validate(String endpointUrl) throws IOException {
+    final URI uri;
+    try {
+      uri = new URI(endpointUrl);
+    } catch (URISyntaxException e) {
+      throw new IOException("Invalid pipeline element endpoint", e);
+    }
+
+    if (uri.getHost() == null
+        || uri.getUserInfo() != null
+        || (!"http".equalsIgnoreCase(uri.getScheme()) && !"https".equalsIgnoreCase(uri.getScheme()))) {
+      throw new IOException("Invalid pipeline element endpoint");
+    }
+
+    for (InetAddress address : InetAddress.getAllByName(uri.getHost())) {
+      if (!isPublicAddress(address)) {
+        throw new IOException("Pipeline element endpoints must not resolve to a local or private address");
+      }
+    }
+
+    return uri;
+  }
+
+  private static boolean isPublicAddress(InetAddress address) {
+    if (address.isAnyLocalAddress()
+        || address.isLoopbackAddress()
+        || address.isLinkLocalAddress()
+        || address.isSiteLocalAddress()
+        || address.isMulticastAddress()) {
+      return false;
+    }
+
+    byte[] bytes = address.getAddress();
+    if (address instanceof Inet4Address) {
+      int first = Byte.toUnsignedInt(bytes[0]);
+      int second = Byte.toUnsignedInt(bytes[1]);
+
+      return first != 0
+          && !(first == 100 && second >= 64 && second <= 127)
+          && !(first == 192 && second == 0)
+          && !(first == 198 && (second == 18 || second == 19))
+          && first < 224;
+    }
+
+    if (address instanceof Inet6Address) {
+      int first = Byte.toUnsignedInt(bytes[0]);
+      return first >= 0x20 && first <= 0x3f;
+    }
+
+    return false;
+  }
+}

